// priority: 2650
// Gregtech Grindless - EMI information pages of the UV era multiblocks (kubejs/assets/emi/recipe/additions/grindless/<id>.json, type emi:info).
// One page per controller: what it does, its circuit modes, what it needs. Their recipes show in EMI under the controller itself.
// Every key is in en_us and es_es.
ClientEvents.lang('en_us', event => {
    var add = function (key, value) { event.add('grindless', key, value) }

    add('emi.grindless.info.accelerator_driven_reactor.0', "The Accelerator-Driven Reactor is a generator: it burns a thorium oxide or thorium nitride fuel assembly in 1000 mB of lead-bismuth eutectic and gives 1,572,864 EU/t.")
    add('emi.grindless.info.accelerator_driven_reactor.1', "It leaves a spent fuel assembly and polonium-210. The spent assembly goes to the Pyroprocessing Cell.")
    add('emi.grindless.info.accelerator_driven_reactor.2', 'A subcritical thorium core driven by a proton beam on a lead-bismuth target, as in MYRRHA and Rubbia\'s energy amplifier. It gives 1,572,864 EU/t and cannot run away: with the beam off, it stops.')
    add('emi.grindless.info.accelerator_driven_reactor.3', 'One thorium oxide assembly burns for 12,000 ticks; a nitride one for 16,000. The lead-bismuth charge is never used up; the target\'s polonium-210 stays in the output hatch. Four SRF cryomodules in the back wall carry the beam.')
    add('emi.grindless.info.accelerator_driven_reactor.4', 'The spent assembly goes to the pyroprocessing cell. Parts go in the bottom layer: 1-4 energy output hatches, an input bus, an input hatch, an output bus, an output hatch.')

    add('emi.grindless.info.amorphous_ice_annealer.0', "The Amorphous Ice Annealer warms a planetesimal sample into water, carbon monoxide, nitrogen and Kuiper noble gas. It only works in Pluto orbit.")
    add('emi.grindless.info.amorphous_ice_annealer.1', "It has no output bus: the inert dust stays in the machine.")
    add('emi.grindless.info.amorphous_ice_annealer.2', 'Amorphous ice that never warmed above 40 K holds argon, krypton and xenon; warmed through its crystallisation at about 140 K, it lets them go in one pulse.')
    add('emi.grindless.info.amorphous_ice_annealer.3', 'Circuit 1: 1 planetesimal sample -> 4,000 mB water + 1,000 mB carbon monoxide + 500 mB nitrogen + 250 mB Kuiper noble gas. The refractory dust (inert silicates and carbon) is voided.')
    add('emi.grindless.info.amorphous_ice_annealer.4', 'Pluto orbit only. The only maker of the Kuiper noble gas: the cryogenic plant splits it into argon, krypton and xenon for the thruster works. Carbon monoxide goes to the syngas plant.')
    add('emi.grindless.info.amorphous_ice_annealer.5', 'Needs 5 x 5 x 7 station truss casing (8 or more among the parts), cryostat casing (the warming stage), tungsten steel pipe casing (the gas manifold), 1 or 2 energy hatches (UV), input buses and 1 to 4 output hatches.')

    add('emi.grindless.info.antimatter_trap.0', "The Antimatter Trap works with antiprotons. Circuit 1: stacks 4 cartridges into a charged trap. Circuit 2: ICAN pellets from the trap, uranium dust and deuterium-tritium. Circuit 3: antihydrogen cartridge. Circuit 4: positronium condensate.")
    add('emi.grindless.info.antimatter_trap.1', "It needs superfluid helium and only works in Earth orbit.")
    add('emi.grindless.info.antimatter_trap.2', 'A Penning trap like CERN\'s BASE: a superconducting solenoid and an electron cooler hold antiprotons in a vacuum no ground site can match. It works only in Earth orbit.')
    add('emi.grindless.info.antimatter_trap.3', 'Circuit 1: four antiproton cartridges stacked into one charged trap (superfluid helium in, helium out; the cartridges come back empty). 2: the trap fires antiprotons into uranium and D-T to make 4 ICAN pellets, and comes back empty.')
    add('emi.grindless.info.antimatter_trap.4', 'Antiprotons that touch matter annihilate to pions and gamma rays: nothing is left to store. Parts go in the bottom layer: 1-2 energy hatches, 1-2 input buses, an input hatch, 1-2 output buses, an output hatch.')

    add('emi.grindless.info.ark_biosphere.0', "The Ark Biosphere is a closed ecosystem. Circuit 1: the closed cycle, where algae and archaeal culture turn CO2, ammonia and water into oxygen, growth medium and biomass. Circuit 2: culture seed, which today turns 1 algae and 1 archaeal culture with 1000 mB of biomass into 2 of each. Circuit 3: inoculates algae from agar.")
    add('emi.grindless.info.ark_biosphere.1', "It needs no other starting point than its own cultures.")
    add('emi.grindless.info.ark_biosphere.2', 'The greenhouse family\'s step 7: a closed ecosystem. Programmed circuit 1: 1,000 mB carbon dioxide + 250 mB ammonia + 1,000 mB water -> 500 mB oxygen + 500 mB raw growth medium + 250 mB biomass.')
    add('emi.grindless.info.ark_biosphere.3', 'Circuit 1 needs an algae culture and an archaeal culture in the input bus (not consumed): the algae turn the CO2 back into oxygen, the archaea in the core make the medium.')
    add('emi.grindless.info.ark_biosphere.4', 'Circuit 2: 1 algae culture + 1 archaeal culture + 1,000 mB biomass -> 2 of each. Circuit 3: 1 agar dust + 1,000 mB biomass + 1,000 mB water -> 1 algae culture. Biomass goes to the biorefinery.')
    add('emi.grindless.info.ark_biosphere.5', 'Needs an 11 x 9 x 11 dome: UV machine casing floor (the parts, 90 or more casings) and footing, laminated glass walls and cap, a 7 x 7 glass tube ring under GT lamps, a 3 x 3 x 3 inert casing core; 1 or 2 energy hatches (UV).')

    add('emi.grindless.info.boron_nitride_reactor.0', "The Boron Nitride Reactor makes boron nitride materials. Circuit 1: hBN. Circuit 2: BNNT. Circuit 3: BNNT yarn. Circuit 4: hBN from boron-10 trifluoride. Circuit 5: BN interphase on SiC fibre. Circuit 6: BN-coated CNT yarn.")
    add('emi.grindless.info.boron_nitride_reactor.1', "The yarns go into tanks and tethers.")
    add('emi.grindless.info.boron_nitride_reactor.2', 'Hexagonal boron nitride and boron nitride nanotubes: as strong as carbon nanotubes, stable to 900 C in air. Circuit 1: 2 boron trioxide + 2,500 mB ammonia -> 2 hBN + 3,000 mB steam + 500 mB ammonia back.')
    add('emi.grindless.info.boron_nitride_reactor.3', 'Circuit 2: 1 hBN + 500 mB hydrogen -> 1 BNNT dust in the induction plasma (the hydrogen comes back). Circuit 3: 5 BNNT dust -> 1 BNNT yarn + 1 hBN (the fines go back to circuit 2).')
    add('emi.grindless.info.boron_nitride_reactor.4', 'Circuit 4: 1,000 mB boron-10 trifluoride (the hot cell\'s enrichment tails) + 1,000 mB ammonia -> 1 hBN + 3,000 mB hydrofluoric acid. The only maker of BNNT yarn.')
    add('emi.grindless.info.boron_nitride_reactor.5', 'Needs 7 x 7 x 9 UV casing (8 or more among the parts), naquadah coils, PTFE pipe casing, tungsten steel gearboxes, 1 or 2 energy hatches (UV), input and output buses and hatches.')

    add('emi.grindless.info.cryotank_winder.0', "The Cryotank Winder builds the BNNT fuel tank from an aerogel tank, BNNT or CNT yarn, hBN, the Pluto-Kuiper chart and epoxy.")
    add('emi.grindless.info.cryotank_winder.1', "It is the tank for level-7 rockets with elite motors.")
    add('emi.grindless.info.cryotank_winder.2', 'The tier 11 fuel tank: with elite motors it builds a level 7 rocket. Circuit 1: 1 aerogel fuel tank + 16 BNNT yarn + 16 carbon nanotube yarn + 4 hBN dust + 1,000 mB epoxy -> 1 BNNT fuel tank.')
    add('emi.grindless.info.cryotank_winder.3', 'The hBN liner is the best thin barrier to hydrogen; BNNT and carbon nanotube yarn overwrap it. The Pluto-Kuiper chart is the mission specification and is not consumed.')
    add('emi.grindless.info.cryotank_winder.4', 'The resin trim is inert cured epoxy and is voided. The only maker of the BNNT fuel tank.')
    add('emi.grindless.info.cryotank_winder.5', 'Needs 7 x 7 x 9 UV casing (8 or more among the parts), tungsten steel frames (the mandrel), assembly line units (the winding head), cupronickel coils (the curing oven), 1 or 2 energy hatches (UV), input buses, an input hatch and an output bus.')

    add('emi.grindless.info.event_horizon_interferometer.0', "The Event Horizon Interferometer combines an HPGe crystal, 4 data orbs and the multimessenger catalogue into the Sagittarius A* image. It only works in Pluto orbit.")
    add('emi.grindless.info.event_horizon_interferometer.1', "The Baseline Astrometer uses the image.")
    add('emi.grindless.info.event_horizon_interferometer.2', 'Observatory step 8: a baseline from Pluto\'s orbit to Earth resolves the shadow of Sgr A*, the black hole at the galaxy\'s heart.')
    add('emi.grindless.info.event_horizon_interferometer.3', 'Circuit 1: the multimessenger catalogue (not consumed) + 1 HPGe crystal (the receiver\'s front end) + 4 data orbs -> 1 Sgr A* image.')
    add('emi.grindless.info.event_horizon_interferometer.4', 'Pluto orbit only. The Event Horizon Telescope imaged Sgr A* in 2022 with an Earth-sized baseline; this one is a fictional stretch of space VLBI. The image is the UHV energy hatch\'s research.')
    add('emi.grindless.info.event_horizon_interferometer.5', 'Needs 9 x 9 x 5 station truss casing (20 or more among the parts), a 7 x 7 dish of aluminium blocks, an advanced computer casing (the maser clock), 1 or 2 energy hatches (UV), input buses and output buses.')

    add('emi.grindless.info.fibre_draw_tower.0', "The Fibre Draw Tower makes optical fibre products. Circuit 1: Yb preform. 2: draw fibre. 3: fibre laser module. 4: refurbish a spent module. 5: 1083 nm laser. 6: hollow capillaries. 7: MCP multifibre. 8: cooling lasers. 9: silica storage preform. 10: Er:YSO pigtail. 11: Er MCVD preform.")
    add('emi.grindless.info.fibre_draw_tower.1', "The fibre laser module is consumed by other machines, which return it spent for refurbishing here.")
    add('emi.grindless.info.fibre_draw_tower.2', 'Ytterbium-doped double-clad fibre and the fibre laser module, the light source of UV\'s lasers. Programmed circuit 1: silicon tetrachloride + germanium tetrachloride + ytterbium oxide + aluminium + oxygen -> 1 Yb-doped preform (MCVD).')
    add('emi.grindless.info.fibre_draw_tower.3', 'Circuit 2: 1 preform + 250 mB acrylate coating -> 16 ytterbium fibre spools. Circuit 3: 4 fibre spools + 4 InGaAs pump modules + 1 fibre Bragg grating -> 1 fibre laser module.')
    add('emi.grindless.info.fibre_draw_tower.4', 'Circuit 4: 1 spent laser module + 1 fibre spool -> 1 fibre laser module (refurbished). The chlorine goes back to silicon tetrachloride, the silica soot to glass.')
    add('emi.grindless.info.fibre_draw_tower.5', 'Needs a 5 x 15 x 5 clean room casing tower (6 or more among the floor parts), 1 or 2 energy hatches (UV), input and output buses and hatches.')

    add('emi.grindless.info.heat_source_works.0', "The Heat Source Works builds radioisotope heat sources. Circuit 1: curium pellet. 2: GPHS cladding. 3: probe RTG. 4: americium micro source. 5: curium RTG pellet.")
    add('emi.grindless.info.heat_source_works.1', "It never voids: heavy curium oxide is kept for the transuranium line.")
    add('emi.grindless.info.heat_source_works.2', 'Curium-244 heat sources behind hot cell walls. Programmed circuit 1: 4 curium oxide -> 1 curium-244 pellet + 1 heavy curium oxide (stored for UHV). Circuit 2: 1 pellet + 1 iridium foil + 1 carbon-carbon aeroshell -> 1 GPHS module (+ iridium scrap, 25%).')
    add('emi.grindless.info.heat_source_works.3', 'Circuit 3: 4 GPHS modules + 8 silicon dust + 8 germanium dust + 1 UV machine hull -> 1 probe RTG. Circuit 4: 1 americium dust -> 8 americium micro sources.')
    add('emi.grindless.info.heat_source_works.4', 'Circuit 5: 1 curium-244 pellet -> 2 curium RTG pellets; IV\'s RTG cell burns one for 3 times as long as a plutonium pellet. The scrap melts back into the iridium foil route.')
    add('emi.grindless.info.heat_source_works.5', 'Needs, in the front and back rows: 1 or 2 energy hatches (ZPM), 1 or 2 input buses, 1 or 2 output buses, and 4 or more radiation proof casings among them. Refuses to run while it voids.')

    add('emi.grindless.info.kuiper_interceptor_bay.0', "The Kuiper Interceptor Bay launches a Kuiper interceptor with the Pluto-Kuiper chart and returns a planetesimal sample and a sample canister. It only works in Pluto orbit.")
    add('emi.grindless.info.kuiper_interceptor_bay.1', "The sample goes to the Amorphous Ice Annealer.")
    add('emi.grindless.info.kuiper_interceptor_bay.2', 'A cold classical Kuiper Belt object, untouched since the Solar System formed. Circuit 1: 1 Kuiper interceptor + the Pluto-Kuiper chart (not consumed) -> 1 planetesimal sample + 1 empty sample canister.')
    add('emi.grindless.info.kuiper_interceptor_bay.3', 'The interceptor flies out on its ion and Hall thrusters, kept warm by its RTG, and brings the canister back to the station, as Hayabusa2 did from Ryugu.')
    add('emi.grindless.info.kuiper_interceptor_bay.4', 'Pluto orbit only. The only maker of the planetesimal sample; the canister goes back into the next interceptor.')
    add('emi.grindless.info.kuiper_interceptor_bay.5', 'Needs 7 x 7 x 9 station truss casing (12 or more among the parts), titanium frames (the launch rail), laminated glass (the sample airlock), 1 or 2 energy hatches (UV), input buses and output buses.')

    add('emi.grindless.info.laser_fusion_chamber.0', "The Laser Fusion Chamber is a generator of 2,621,440 EU/t. Circuit 1: p-B11 capsule. Circuit 2: D-He3 capsule. Each run needs a fibre laser module.")
    add('emi.grindless.info.laser_fusion_chamber.1', "The spent laser module comes back and can be refurbished.")
    add('emi.grindless.info.laser_fusion_chamber.2', 'Proton-boron-11 fusion: three alpha particles and almost no neutrons. One capsule per run pays 2,621,440 EU/t (5 A UV). Programmed circuit 1: 1 p-B11 capsule, 400 ticks, 3,000 mB helium. Circuit 2: 1 D-He-3 capsule, 600 ticks, 1,000 mB helium + 1,000 mB hydrogen.')
    add('emi.grindless.info.laser_fusion_chamber.3', 'Each run has a 2% chance to wear out 1 fibre laser module into a spent laser module. The helium goes to the helium refrigerator.')
    add('emi.grindless.info.laser_fusion_chamber.4', 'A 13x13x13 chamber of UV casing with a ring of 32 laser module blocks round its waist. In the floor: 1-8 dynamo hatches, 1 input bus (the capsule injector), 1-2 output hatches, 1 output bus.')

    add('emi.grindless.info.laser_sail_launcher.0', "The Laser Sail Launcher fires sails from the Moon. Circuit 1: launches the Starshot probe (sailcraft, heliopause data and a fibre laser module). Circuit 2: launches the relay seed.")
    add('emi.grindless.info.laser_sail_launcher.1', "It only works on the Moon.")
    add('emi.grindless.info.laser_sail_launcher.2', 'Works only on the Moon: no air to scatter the beam. A 15 x 15 x 3 phased array of 64 laser module blocks, open to the sky.')
    add('emi.grindless.info.laser_sail_launcher.3', 'Four 4 x 4 quadrants of modules, a tungstensteel cooling loop round them, the beam director (a computer casing) in the centre.')
    add('emi.grindless.info.laser_sail_launcher.4', 'One sail-chip a launch, aimed with the heliopause data (kept): one Starshot probe in flight. Draws 16 A of UV.')
    add('emi.grindless.info.laser_sail_launcher.5', 'Each launch wears the array: a fibre laser module from the bus is spent at 64 % and comes out as a spent module for the draw tower.')

    add('emi.grindless.info.light_sail_fab.0', "The Light Sail Fab builds sail parts. Circuit 1: nitride film. 2: metasurface pattern. 3: sail release. 4: aluminium reflector film. It only works in Earth orbit.")
    add('emi.grindless.info.light_sail_fab.1', "The reflector film is also used for swarm segments.")
    add('emi.grindless.info.light_sail_fab.2', 'Works only in Earth orbit: a film 100 nm thick cannot survive gravity and air once it is released.')
    add('emi.grindless.info.light_sail_fab.3', 'A 7 x 7 x 7 box of station truss: a 3 x 3 tungsten heater on the back wall, a whipple shield wall in front of it, parts in the floor.')
    add('emi.grindless.info.light_sail_fab.4', 'Circuit 1: silane and ammonia lay silicon nitride on an epitaxial wafer. 2: patterned into an hBN metasurface under the X-ray mask (kept).')
    add('emi.grindless.info.light_sail_fab.5', 'Circuit 3: xenon difluoride etches the silicon away and frees the sail; the xenon comes back, the silicon tetrafluoride is hydrolysed.')

    add('emi.grindless.info.mocvd_reactor.0', "The MOCVD Reactor grows semiconductor layers. Circuit 1: organometallics. 2: InGaAs epi. 3: diode bars. 4: NbN film. 5: pump module. 6: arsine scrubbing. 7: IMM epi. 8: NbN SiC plate. 12: InGaAsSb epi.")
    add('emi.grindless.info.mocvd_reactor.1', "The wafers feed lasers, pump modules and solar arrays.")
    add('emi.grindless.info.mocvd_reactor.2', 'Compound semiconductors grown atom layer by atom layer. Circuit 1: gallium + indium + sodium + chloromethane -> trimethylgallium + trimethylindium + salt.')
    add('emi.grindless.info.mocvd_reactor.3', 'Circuit 2: 1 GaAs wafer + trimethylgallium + trimethylindium + arsine -> 1 InGaAs epi wafer + methane + unused arsine. Circuit 3: 1 epi wafer -> 8 diode bars. Circuit 5: 4 diode bars + 2 copper plates -> 1 InGaAs pump module.')
    add('emi.grindless.info.mocvd_reactor.4', 'Circuit 4: 1 sapphire wafer + niobium + nitrogen -> 1 NbN film wafer. Circuit 6, the arsine scrubber: 1,000 mB arsine -> 1 arsenic dust + 3,000 mB hydrogen. Arsine is never vented.')
    add('emi.grindless.info.mocvd_reactor.5', 'Needs 7 x 7 x 7 clean room casing with an inert gas cabinet (8 or more among the parts), 1 or 2 energy hatches (UV), input and output buses and hatches.')

    add('emi.grindless.info.muon_fusion_cell.0', "The Muon Fusion Cell is a generator with no circuit: a lithium breeder blanket and 500 mB of liquid deuterium-tritium give 500 mB of helium and 150 mB of tritium.")
    add('emi.grindless.info.muon_fusion_cell.1', "It runs without a circuit.")
    add('emi.grindless.info.muon_fusion_cell.2', 'Muons from a pion target drop into liquid deuterium-tritium and catalyse fusion at 20 K (Alvarez 1956, LAMPF, J-PARC). It gives 786,432 EU/t. An extrapolation: real muon-catalysed fusion has never reached break-even; this cell assumes a far lower sticking fraction.')
    add('emi.grindless.info.muon_fusion_cell.3', '500 mB of liquid D-T burn in 1,200 ticks to helium. The lithium blanket (never used up) breeds back 60 % of the tritium; the other 40 % is make-up from the tritium removal facility. Helium goes to the superfluid helium plant.')
    add('emi.grindless.info.muon_fusion_cell.4', 'Two SRF cryomodules in the back wall drive the pion beam. Parts go in the bottom layer: 1-2 energy output hatches, an input bus, an input hatch, 1-2 output hatches.')

    add('emi.grindless.info.neptune_deep_siphon.0', "The Neptune Deep Siphon draws gas from Neptune. Circuit 4: Neptune hydrogen and helium. Circuit 5: methane and hydrogen sulfide. It needs a Neptune sample and a scoop head, and only works in Neptune orbit.")
    add('emi.grindless.info.neptune_deep_siphon.1', "It keeps every output: nothing is voided.")
    add('emi.grindless.info.neptune_deep_siphon.2', 'Lowers the scoop on a longer tether, below Neptune\'s methane deck. The Neptune sample (kept) tells it how deep. Runs only the siphon type\'s Neptune rows (the Ice-Giant Siphon refuses them). Only works in Neptune orbit.')
    add('emi.grindless.info.neptune_deep_siphon.3', 'Circuit 4: 16,000 mB Neptune hydrogen + 4,000 mB Neptune helium. 5: 4,000 mB methane + 500 mB hydrogen sulfide. 491,520 EU/t (UV), 100 t. The scoop head wears (0.25 % per run).')
    add('emi.grindless.info.neptune_deep_siphon.4', 'Needs: 1 or 2 energy hatches (UV), 1 or 2 input buses, 1 to 3 output hatches, and 14 or more station truss casings in the floor. The tether winch stands in the middle.')

    add('emi.grindless.info.neural_culture_vat.0', "The Neural Culture Vat grows neural tissue. Circuit 1: 64 stem cells from gelatin, neural organoid and growth medium. Circuit 2: 4 neural processing units from 8 stem cells and a wetware PCB.")
    add('emi.grindless.info.neural_culture_vat.1', "The stem cells are also what the organoid computers of UHV start from.")
    add('emi.grindless.info.neural_culture_vat.2', 'Wetware in batches; GTM\'s own stem cell and neuro processing unit recipes still work. Circuit 1: 1,000 mB raw growth medium + 4 gelatin dust -> 64 stem cells + 250 mB biomass.')
    add('emi.grindless.info.neural_culture_vat.3', 'Circuit 1 needs a neural organoid (from the organoid lab) in the input bus, not consumed: it seeds the culture.')
    add('emi.grindless.info.neural_culture_vat.4', 'Circuit 2: 8 stem cells + 1 wetware printed circuit board + 1,000 mB sterilised growth medium -> 4 neuro processing units + 250 mB biomass. Failed cultures are autoclaved inside.')
    add('emi.grindless.info.neural_culture_vat.5', 'Needs a 7 x 7 x 7 plascrete room: cleanroom glass windows, a 3 x 3 filter casing ceiling, four heatproof casing incubators and a robust casing bioprinter; parts in the floor (30 or more casings), 1 or 2 energy hatches (UV).')

    add('emi.grindless.info.optical_ground_station.0', "The Optical Ground Station turns a Starshot probe, an SNSPD array and 100 mB of superfluid helium into the Proxima approach data. It has no circuit.")
    add('emi.grindless.info.optical_ground_station.1', "The data is needed to open the warp gate and to send the rover.")
    add('emi.grindless.info.optical_ground_station.2', 'The only reader of the Starshot: it catches the probe\'s laser photons from four light years away and decodes them into Proxima approach data.')
    add('emi.grindless.info.optical_ground_station.3', '1 Starshot probe in flight + 100 mB superfluid helium -> 1 Proxima approach data + 100 mB helium. Needs an SNSPD array in the input bus (not consumed).')
    add('emi.grindless.info.optical_ground_station.4', 'The SNSPD array is made in the ZPM qubit fab (circuit 3) from an NbN film wafer. The boiled-off helium goes back to the vacuum freezer.')
    add('emi.grindless.info.optical_ground_station.5', 'Needs a 9 x 9 x 9 UV machine casing dome: a 5 x 5 aluminium block mirror on the floor, 3 computer casings behind it, the roof open in the middle; parts in the floor (50 or more casings), 1 or 2 energy hatches (UV).')

    add('emi.grindless.info.penetrator_probe_bay.0', "The Penetrator Probe Bay fires a penetrator probe at a moon. Circuit 1: Sputnik core. Circuit 2: Charon core. It only works in Pluto orbit.")
    add('emi.grindless.info.penetrator_probe_bay.1', "Nothing is voided; the cores go to the Volatile Ice Fractionator.")
    add('emi.grindless.info.penetrator_probe_bay.2', 'Drops a penetrator into Sputnik Planitia or onto Charon and catches the core it sends up. The Triton ice core (kept) calibrates it for Kuiper ices. Only works in Pluto orbit.')
    add('emi.grindless.info.penetrator_probe_bay.3', 'Circuit 1: 1 penetrator probe -> 1 Sputnik ice core. Circuit 2: 1 penetrator probe -> 1 Charon core. 491,520 EU/t (UV), 200 t.')
    add('emi.grindless.info.penetrator_probe_bay.4', 'Needs: 1 or 2 energy hatches (UV), 1 or 2 input buses, 1 or 2 output buses, and 14 or more station truss casings in the floor. A titanium probe rail runs up the middle to the canister catcher (tungstensteel gearbox).')

    add('emi.grindless.info.powder_bed_printer.0', "The Powder Bed Printer makes metal parts. Circuit 1: atomises powder. 2: near-net gear or rotor. 3: press. 4: thruster chamber. 5: array mount. 6: probe frame. 7: Rhea impeller. 8: tungsten mesh.")
    add('emi.grindless.info.powder_bed_printer.1', "Each print consumes a fibre laser module.")
    add('emi.grindless.info.powder_bed_printer.2', 'UV parts in one piece with less metal. Circuit 1 atomises: 4 ingots + 1,000 mB argon -> 4 AM powder + 950 mB argon.')
    add('emi.grindless.info.powder_bed_printer.3', 'Printing burns a fibre laser module (2 % wear: a spent module comes out at the same chance). Circuit 2: neutronium and tritanium gears and darmstadtium rotors at 75 % of the ingots; circuits 4 to 6: the thruster chamber, the array mount and the probe frame.')
    add('emi.grindless.info.powder_bed_printer.4', 'Circuit 3 presses the near-net part: + 1,000 mB argon -> the part, all the argon back. The unsintered powder and the spatter go back to the bed.')
    add('emi.grindless.info.powder_bed_printer.5', 'Needs 7 x 7 x 7 UV casing (8 or more among the parts), naquadah coils, PTFE pipe casing, assembly line grating, tungsten steel firebox casing and frames, 1 or 2 energy hatches (UV), input and output buses and hatches.')

    add('emi.grindless.info.powder_in_tube_line.0', "The Powder-in-Tube Line makes superconducting wire. Circuit 1: EnTED powder. 2: billet. 3: EnTED wire. 4: RTAN wire. 5: MgB2 wire in an iron tube. 6: LaY superhydride wire.")
    add('emi.grindless.info.powder_in_tube_line.1', "The wires are used for superconducting hatches and structures of the later eras.")
    add('emi.grindless.info.powder_in_tube_line.2', 'EnTED wire, GTM\'s UV superconductor, at four wires per ingot of powder. Circuit 1: 4 enriched naquadah + 3 trinium + 2 europium + 1 duranium dust -> 10 EnTED powder.')
    add('emi.grindless.info.powder_in_tube_line.3', 'Circuit 2: 4 EnTED powder + 1 silver tube -> 1 PIT billet. Circuit 3: 1 billet -> 16 EnTED single wires + 1 silver dust (the sheath, back into tubes).')
    add('emi.grindless.info.powder_in_tube_line.4', 'The only maker of EnTED wire: the wiremill, extruder and wire cutter routes are gone. Doubling, fine wire and cables still start from its single wire.')
    add('emi.grindless.info.powder_in_tube_line.5', 'Needs a 3 x 5 x 15 line of UV casing (8 or more among the parts), steel pipe casing, tungsten steel gearboxes, assembly line units, trinium coils, 1 or 2 energy hatches (UV), input and output buses.')

    add('emi.grindless.info.precursor_probe_bay.0', "The Precursor Probe Bay flies a precursor probe with 4 ICAN pellets and returns the heliopause data. It only works in Pluto orbit.")
    add('emi.grindless.info.precursor_probe_bay.1', "The data is used by the Laser Sail Launcher and the Solar Probe Bay.")
    add('emi.grindless.info.precursor_probe_bay.2', 'The first probe to the heliopause, where the Sun\'s wind meets the interstellar medium. Circuit 1: 1 precursor probe + 4 ICAN pellets -> 1 heliopause data.')
    add('emi.grindless.info.precursor_probe_bay.3', 'An ICAN kick out of Pluto\'s orbit, then years on ion thrusters to 150 AU, as JHU/APL\'s Interstellar Probe study planned after Voyager 1 crossed in 2012. The probe is spent.')
    add('emi.grindless.info.precursor_probe_bay.4', 'Pluto orbit only, 2 A UV. The only maker of the heliopause data: the laser sail launcher needs it to aim the Starshot.')
    add('emi.grindless.info.precursor_probe_bay.5', 'Needs 7 x 7 x 11 station truss casing (16 or more among the parts), titanium frames (the launch rail), computer casing (the DSN relay), 1 or 2 energy hatches (UV), input buses and output buses.')

    add('emi.grindless.info.pyroprocessing_cell.0', "The Pyroprocessing Cell reprocesses fuel. Circuit 1: reduces spent oxide fuel to ThU metal. 2: refines U-233 and thorium. 3: nitride fuel (N-15 comes back). 4: cleans the loaded salt. 5: HFIR driver row. 6: Ti-50 sponge. 7: Ni-58 metal. 8: Li-6 metal. 9: Li-Sn eutectic.")
    add('emi.grindless.info.pyroprocessing_cell.1', "It refuses to void.")
    add('emi.grindless.info.pyroprocessing_cell.2', 'The molten-salt pyroprocess of EBR-II: spent thorium fuel is reduced with lithium in a LiCl bath and the uranium-233 is collected on a cathode.')
    add('emi.grindless.info.pyroprocessing_cell.3', 'Circuit 1: spent oxide fuel to thorium-uranium metal. 2: the metal to uranium-233 and thorium. 3: spent nitride fuel to uranium-233, thorium and nitrogen-15 (5 % N-14 make-up). 4: the loaded salt cleaned; its waste goes to the waste retrieval plant. 5: spent high flux reactor drivers back to uranium-233.')
    add('emi.grindless.info.pyroprocessing_cell.4', 'The salt and the lithium are charges that are never used up. Parts go in the bottom layer: 1-2 energy hatches, an input bus, 1-2 input hatches, 1-2 output buses, 1-2 output hatches.')

    add('emi.grindless.info.srf_cavity_works.0', "The SRF Cavity Works builds superconducting cavities. Circuit 1: RRR niobium sheets. 2: bare cavity. 3: surface treatment with electropolish acid. 4: cryomodule (needs superfluid helium). 5: Nb3Sn diffusion and para-H2 target. 6: polarised H ice. 7: solid neon cone.")
    add('emi.grindless.info.srf_cavity_works.1', "The cavities are parts for accelerators and cryomodules.")
    add('emi.grindless.info.srf_cavity_works.2', 'The superconducting radio-frequency cryomodule, the building block of every UV accelerator. Programmed circuit 1: 4 niobium ingots -> 3 RRR niobium sheets + 1 niobium scrap (the scrap melts back into an ingot).')
    add('emi.grindless.info.srf_cavity_works.3', 'Circuit 2: 9 RRR sheets -> 1 bare cavity. Circuit 3: 1 bare cavity + 500 mB electropolish acid + 100 mB nitrogen -> 1 N-doped cavity + 500 mB spent acid.')
    add('emi.grindless.info.srf_cavity_works.4', 'Circuit 4: 8 cavities + 4,000 mB superfluid helium + 2 UV field generators + 1 mu-metal shield -> 1 SRF cryomodule. The spent acid is recovered as niobium and fluorite, and fluorite makes hydrofluoric acid again.')
    add('emi.grindless.info.srf_cavity_works.5', 'Needs 7 x 7 x 9 clean room casing (8 or more among the parts), 1 or 2 energy hatches (UV), input and output buses and hatches.')

    add('emi.grindless.info.starchip_fab.0', "The Starchip Fab builds interstellar hardware. Circuit 1: starchip. 2: sailcraft. 3: relay seed. 4: ergosphere probe. It only works in Earth orbit and needs a clean room.")
    add('emi.grindless.info.starchip_fab.1', "Sailcraft and relay seeds are launched by the Laser Sail Launcher.")
    add('emi.grindless.info.starchip_fab.2', 'A 5 x 5 x 5 clean room box with a filter casing ceiling and the bonder (a stainless steel gearbox) in the middle of the floor.')
    add('emi.grindless.info.starchip_fab.3', 'Circuit 1: a photonic chip, an NV diamond chip and an americium micro source bonded on a neutronium wafer: a starchip of a few grams.')
    add('emi.grindless.info.starchip_fab.4', 'Circuit 2: the starchip mounted on a light sail: a sail-chip ready for the launcher on the Moon.')
    add('emi.grindless.info.starchip_fab.5', 'The wafer kerf comes out as silicon dust.')

    add('emi.grindless.info.superfluid_helium_plant.0', "The Superfluid Helium Plant has no circuit. It makes superfluid helium from liquid helium, or from Neptune helium (with a helium-3 concentrate byproduct), mixes helium-3 and helium-4, and splits PLi6 ash into helium-3 and helium.")
    add('emi.grindless.info.superfluid_helium_plant.1', "Superfluid helium cools the cavities, the antimatter trap and the optical station.")
    add('emi.grindless.info.superfluid_helium_plant.2', 'Helium II at 1.9 K, below the lambda point, which LuV\'s 4 K refrigerator cannot reach. It cools the SRF cavities and the SNSPD receiver.')
    add('emi.grindless.info.superfluid_helium_plant.3', 'Liquid helium (from the helium refrigerator): 1,000 mB -> 1,000 mB superfluid helium. Fluid recipes only: no circuit.')
    add('emi.grindless.info.superfluid_helium_plant.4', 'Superleak: 1,000 mB Neptune helium -> 990 mB superfluid helium + 10 mB helium-3 concentrate (only helium-4 passes). The concentrate goes to the isotope column.')
    add('emi.grindless.info.superfluid_helium_plant.5', 'Needs 7 x 7 x 9 frostproof casing (8 or more among the parts), 1 or 2 energy hatches (UV), 1 or 2 input hatches and 1 or 2 output hatches.')

    add('emi.grindless.info.synchrotron.0', "The Synchrotron works with X-rays. Circuit 1: exposes a PMMA wafer. 2: LIGA develop. 3: photonic chips. 4: antiprotons (the activated tungsten target comes back as a byproduct). 5: sodium-22 target. 6: SiN waveguide lithography. 7: damascene trench lithography.")
    add('emi.grindless.info.synchrotron.1', "Antiprotons are made here.")
    add('emi.grindless.info.synchrotron.2', 'A 23 x 23 ring: 16 superconducting dipoles bend the beam, two SRF cryomodules give it energy, two beamlines take it out. Its X-rays run KIT\'s LIGA process; its protons on a tungsten target make the only antiprotons in the pack.')
    add('emi.grindless.info.synchrotron.3', 'Circuit 1: a PMMA-coated wafer exposed under a gold X-ray mask (kept). 2: developed in the LIGA developer (never drained). 3: with a silicon nitride film, 4 photonic chips. 4: 16 protons into one antiproton cartridge; the tungsten target wears 2 % a run and comes out activated.')
    add('emi.grindless.info.synchrotron.4', 'The activated target cools in a chemical bath back to tungsten and copper dust; most of the beam recombines to hydrogen. Parts go in the bottom layer: 1-4 energy hatches, 1-2 input buses, an input hatch, 1-2 output buses, an output hatch.')

    add('emi.grindless.info.thruster_works.0', "The Thruster Works builds propulsion. Circuit 1: ion thruster (xenon). 2: Hall thruster (krypton). 3: thruster pod. 4: ICAN rocket motor. 5: oganesson propellant pod. 6: DFD Mk1 motor. 7: DFD Mk2 motor.")
    add('emi.grindless.info.thruster_works.1', "Oganesson pods are the fuel of the swarm.")
    add('emi.grindless.info.thruster_works.2', 'Electric thrusters for the probes. Circuit 1: 2 molybdenum grids + 1 LaB6 cathode + 1 printed thruster chamber + 4,000 mB xenon -> 1 gridded ion thruster + 3,600 mB xenon.')
    add('emi.grindless.info.thruster_works.3', 'Circuit 2: 1 BN discharge channel + 4 UV electromagnets + 1 LaB6 cathode + 4,000 mB krypton (from the Kuiper noble gas mix) -> 1 Hall thruster + 3,600 mB krypton. The firing loses a tenth of the gas.')
    add('emi.grindless.info.thruster_works.4', 'Circuit 3: 1 gridded ion thruster + 1 Hall thruster + 1 UV circuit (the power processing unit) + 1 propellant tank -> 1 thruster pod.')
    add('emi.grindless.info.thruster_works.5', 'Needs 7 x 7 x 9 UV casing (8 or more among the parts), laminated glass (the vacuum test cell), assembly line grating and units (the assembly bay), 1 or 2 energy hatches (UV), input and output buses and hatches.')

    add('emi.grindless.info.triton_geyser_sampler.0', "The Triton Geyser Sampler works with an aerogel cartridge. Circuit 1: with the Triton probe recording, tholin and Triton nitrogen. Circuit 2: Triton ice core and nitrogen. It only works in Neptune orbit.")
    add('emi.grindless.info.triton_geyser_sampler.1', "Nothing is voided.")
    add('emi.grindless.info.triton_geyser_sampler.2', 'Flies an aerogel cartridge through the nitrogen geysers of Triton. The Triton probe recording (kept) tells it where they erupt. Only works in Neptune orbit.')
    add('emi.grindless.info.triton_geyser_sampler.3', 'Circuit 1: 1 aerogel cartridge -> 8,000 mB Triton nitrogen + 1 tholin. Circuit 2: 1 aerogel cartridge -> 1 Triton ice core + 2,000 mB Triton nitrogen. 491,520 EU/t (UV), 200 t.')
    add('emi.grindless.info.triton_geyser_sampler.4', 'Needs: 1 or 2 energy hatches (UV), 1 or 2 input buses, 1 or 2 output buses, 1 or 2 output hatches, and 14 or more station truss casings in the floor. A titanium launch rail runs through the middle.')

    add('emi.grindless.info.volatile_ice_fractionator.0', "The Volatile Ice Fractionator separates cores. Circuit 1: Sputnik core into tholin, nitrogen, carbon monoxide and methane. Circuit 2: Charon core into silica, water and ammonia. It only works in Pluto orbit.")
    add('emi.grindless.info.volatile_ice_fractionator.1', "Nothing is voided.")
    add('emi.grindless.info.volatile_ice_fractionator.2', 'Warms a core step by step on a cold finger: each ice sublimes at its own temperature (nitrogen, then carbon monoxide, then methane). Only works in Pluto orbit.')
    add('emi.grindless.info.volatile_ice_fractionator.3', 'Circuit 1: 1 Sputnik ice core -> 16,000 mB nitrogen + 2,000 mB carbon monoxide + 1,000 mB methane + 1 tholin. Circuit 2: 1 Charon core -> 8,000 mB water + 2,000 mB ammonia + 1 silicon dioxide dust. 122,880 EU/t (ZPM), 600 t.')
    add('emi.grindless.info.volatile_ice_fractionator.4', 'Needs: 1 or 2 energy hatches (UV), 1 or 2 input buses, 1 or 2 output buses, 1 to 3 output hatches, and 14 or more station truss casings in the floor. The stepped cold finger (steel pipe casings, titanium frames) stands in the middle.')

    add('emi.grindless.info.zone_refining_tower.0', "The Zone Refining Tower purifies crystals. Circuit 1: GeCl4. 2: germanium reduction. 3: HPGe crystal. 4: float-zone silicon. 5: 7N indium. 6: Si-28 float-zone ingot. 7: Si-28 donor regrowth.")
    add('emi.grindless.info.zone_refining_tower.1', "HPGe crystals go into detectors and interferometers.")
    add('emi.grindless.info.zone_refining_tower.2', 'High-purity germanium, thirteen nines, for the HPGe crystal. Programmed circuit 1: 1 germanium dust + 4,000 mB chlorine -> 1,000 mB germanium tetrachloride (also the fibre preform\'s dopant).')
    add('emi.grindless.info.zone_refining_tower.3', 'Circuit 2: 1,000 mB germanium tetrachloride + 2,000 mB water + 4,000 mB hydrogen -> 1 germanium ingot + 4,000 mB hydrochloric acid; the water comes back.')
    add('emi.grindless.info.zone_refining_tower.4', 'Circuit 3: 4 germanium ingots -> 1 HPGe crystal + 1 germanium dust (the impure ends, back to circuit 1). Eight RF coils sweep the melt zone up the bar, the puller grows the crystal.')
    add('emi.grindless.info.zone_refining_tower.5', 'Needs a 3 x 13 x 3 clean room casing tower: 8 naquadah coil blocks in the core and a stainless steel gearbox on top; parts in the floor and the back wall (6 or more casings), 1 or 2 energy hatches (UV).')
})

ClientEvents.lang('es_es', event => {
    var add = function (key, value) { event.add('grindless', key, value) }

    add('emi.grindless.info.accelerator_driven_reactor.0', "El reactor impulsado por acelerador es un generador: quema un ensamblaje de combustible de óxido o nitruro de torio en 1000 mB de eutéctico de plomo y bismuto y da 1.572.864 EU/t.")
    add('emi.grindless.info.accelerator_driven_reactor.1', "Deja un ensamblaje gastado y polonio-210. El ensamblaje gastado puede ir a la celda de piroprocesado.")
    add('emi.grindless.info.accelerator_driven_reactor.2', 'Un núcleo subcrítico de torio impulsado por un haz de protones sobre un blanco de plomo-bismuto, como en MYRRHA y el amplificador de energía de Rubbia. Da 1 572 864 EU/t y no puede desbocarse: sin el haz, se detiene.')
    add('emi.grindless.info.accelerator_driven_reactor.3', 'Un ensamblaje de óxido de torio arde 12 000 ticks; uno de nitruro, 16 000. La carga de plomo-bismuto nunca se gasta; el polonio-210 del blanco se queda en la escotilla de salida. Cuatro criomódulos SRF en la pared trasera llevan el haz.')
    add('emi.grindless.info.accelerator_driven_reactor.4', 'El ensamblaje gastado va a la celda de pirorrefinado. Las piezas van en la capa inferior: 1-4 escotillas de salida de energía, un bus de entrada, una escotilla de entrada, un bus de salida, una escotilla de salida.')

    add('emi.grindless.info.amorphous_ice_annealer.0', "El recocedor de hielo amorfo calienta una muestra de planetesimal hasta obtener agua, monóxido de carbono, nitrógeno y gas noble de Kuiper. Solo funciona en la órbita de Plutón.")
    add('emi.grindless.info.amorphous_ice_annealer.1', "No tiene bus de salida: el polvo inerte se queda dentro de la máquina.")
    add('emi.grindless.info.amorphous_ice_annealer.2', 'El hielo amorfo que nunca pasó de 40 K guarda argón, kriptón y xenón; al calentarse hasta cristalizar, a unos 140 K, los suelta de golpe.')
    add('emi.grindless.info.amorphous_ice_annealer.3', 'Circuito 1: 1 muestra de planetesimal -> 4.000 mB de agua + 1.000 mB de monóxido de carbono + 500 mB de nitrógeno + 250 mB de gas noble de Kuiper. El polvo refractario (silicatos y carbono inertes) se descarta.')
    add('emi.grindless.info.amorphous_ice_annealer.4', 'Solo en la órbita de Plutón. Es la única fuente del gas noble de Kuiper: la planta criogénica lo separa en argón, kriptón y xenón para el taller de propulsores. El monóxido de carbono va a la planta de gas de síntesis.')
    add('emi.grindless.info.amorphous_ice_annealer.5', 'Necesita 5 x 5 x 7 de carcasa de celosía de estación (8 o más entre las piezas), carcasa de criostato (la etapa de calentamiento), carcasa de tubería de acero de tungsteno (el colector de gases), 1 o 2 escotillas de energía (UV), buses de entrada y de 1 a 4 escotillas de salida.')

    add('emi.grindless.info.antimatter_trap.0', "La trampa de antimateria trabaja con antiprotones. Circuito 1: apila 4 cartuchos en una trampa cargada. Circuito 2: pellets ICAN con la trampa, polvo de uranio y deuterio-tritio. Circuito 3: cartucho de antihidrógeno. Circuito 4: condensado de positronio.")
    add('emi.grindless.info.antimatter_trap.1', "Necesita helio superfluido y solo funciona en la órbita de la Tierra.")
    add('emi.grindless.info.antimatter_trap.2', 'Una trampa de Penning como BASE del CERN: un solenoide superconductor y un enfriador de electrones retienen antiprotones en un vacío que ningún sitio en tierra iguala. Solo funciona en órbita terrestre.')
    add('emi.grindless.info.antimatter_trap.3', 'Circuito 1: cuatro cartuchos de antiprotones se apilan en una trampa cargada (entra helio superfluido, sale helio; los cartuchos vuelven vacíos). 2: la trampa dispara antiprotones sobre uranio y D-T para hacer 4 pastillas ICAN, y vuelve vacía.')
    add('emi.grindless.info.antimatter_trap.4', 'Los antiprotones que tocan materia se aniquilan en piones y rayos gamma: no queda nada que guardar. Las piezas van en la capa inferior: 1-2 escotillas de energía, 1-2 buses de entrada, una escotilla de entrada, 1-2 buses de salida, una escotilla de salida.')

    add('emi.grindless.info.ark_biosphere.0', "La biosfera arca es un ecosistema cerrado. Circuito 1: el ciclo cerrado, donde algas y cultivo arqueal convierten CO2, amoníaco y agua en oxígeno, medio de crecimiento y biomasa. Circuito 2: semilla de cultivo, que hoy convierte 1 alga y 1 cultivo arqueal con 1000 mB de biomasa en 2 de cada uno. Circuito 3: inocula algas a partir de agar.")
    add('emi.grindless.info.ark_biosphere.1', "No necesita más punto de partida que sus propios cultivos.")
    add('emi.grindless.info.ark_biosphere.2', 'El paso 7 de la familia de invernaderos: un ecosistema cerrado. Circuito programado 1: 1.000 mB de dioxido de carbono + 250 mB de amoniaco + 1.000 mB de agua -> 500 mB de oxigeno + 500 mB de medio de cultivo crudo + 250 mB de biomasa.')
    add('emi.grindless.info.ark_biosphere.3', 'El circuito 1 necesita un cultivo de algas y un cultivo de arqueas en el bus de entrada (no se consumen): las algas devuelven el CO2 como oxigeno y las arqueas del nucleo hacen el medio.')
    add('emi.grindless.info.ark_biosphere.4', 'Circuito 2: 1 cultivo de algas + 1 cultivo de arqueas + 1.000 mB de biomasa -> 2 de cada. Circuito 3: 1 polvo de agar + 1.000 mB de biomasa + 1.000 mB de agua -> 1 cultivo de algas. La biomasa va a la biorrefineria.')
    add('emi.grindless.info.ark_biosphere.5', 'Necesita una cupula de 11 x 9 x 11: suelo de carcasa de maquina UV (las piezas, 90 o mas carcasas) y zocalo, paredes y techo de vidrio laminado, un anillo de tubos de vidrio de 7 x 7 bajo lamparas GT y un nucleo de carcasa inerte de 3 x 3 x 3; 1 o 2 hatches de energia (UV).')

    add('emi.grindless.info.boron_nitride_reactor.0', "El reactor de nitruro de boro fabrica materiales de nitruro de boro. Circuito 1: hBN. Circuito 2: BNNT. Circuito 3: hilo de BNNT. Circuito 4: hBN a partir de trifluoruro de boro-10. Circuito 5: interfase de BN en fibra de SiC. Circuito 6: hilo de CNT recubierto de BN.")
    add('emi.grindless.info.boron_nitride_reactor.1', "Los hilos se usan en tanques y cables.")
    add('emi.grindless.info.boron_nitride_reactor.2', 'Nitruro de boro hexagonal y nanotubos de nitruro de boro: tan fuertes como los de carbono, estables a 900 C en aire. Circuito 1: 2 de trioxido de boro + 2.500 mB de amoniaco -> 2 hBN + 3.000 mB de vapor + 500 mB de amoniaco de vuelta.')
    add('emi.grindless.info.boron_nitride_reactor.3', 'Circuito 2: 1 hBN + 500 mB de hidrogeno -> 1 polvo de BNNT en el plasma de induccion (el hidrogeno vuelve). Circuito 3: 5 polvos de BNNT -> 1 hilo de BNNT + 1 hBN (los finos vuelven al circuito 2).')
    add('emi.grindless.info.boron_nitride_reactor.4', 'Circuito 4: 1.000 mB de trifluoruro de boro-10 (las colas de enriquecimiento de la celda caliente) + 1.000 mB de amoniaco -> 1 hBN + 3.000 mB de acido fluorhidrico. El unico que hace hilo de BNNT.')
    add('emi.grindless.info.boron_nitride_reactor.5', 'Necesita carcasa UV de 7 x 7 x 9 (8 o mas entre las piezas), bobinas de naquadah, carcasa de tuberia de PTFE, cajas de engranajes de acero de tungsteno, 1 o 2 hatches de energia (UV), buses y hatches de entrada y salida.')

    add('emi.grindless.info.cryotank_winder.0', "El bobinador de criotanques construye el tanque de combustible de BNNT con un tanque de aerogel, hilo de BNNT o CNT, hBN, la carta Plutón-Kuiper y epoxi.")
    add('emi.grindless.info.cryotank_winder.1', "Es el tanque de los cohetes de nivel 7 con motores de élite.")
    add('emi.grindless.info.cryotank_winder.2', 'El tanque de combustible de nivel 11: con motores élite construye un cohete de nivel 7. Circuito 1: 1 tanque de aerogel + 16 hilos de BNNT + 16 hilos de nanotubos de carbono + 4 de polvo de hBN + 1.000 mB de epoxi -> 1 tanque de BNNT.')
    add('emi.grindless.info.cryotank_winder.3', 'El revestimiento de hBN es la mejor barrera fina contra el hidrógeno; los hilos de BNNT y de nanotubos de carbono lo envuelven. La carta Plutón-Kuiper es la especificación de la misión y no se consume.')
    add('emi.grindless.info.cryotank_winder.4', 'Los recortes de resina son epoxi curado inerte y se descartan. Es la única fuente del tanque de combustible de BNNT.')
    add('emi.grindless.info.cryotank_winder.5', 'Necesita 7 x 7 x 9 de carcasa UV (8 o más entre las piezas), bastidores de acero de tungsteno (el mandril), unidades de línea de ensamblaje (el cabezal bobinador), bobinas de cuproníquel (el horno de curado), 1 o 2 escotillas de energía (UV), buses de entrada, una escotilla de entrada y un bus de salida.')

    add('emi.grindless.info.event_horizon_interferometer.0', "El interferómetro del horizonte de sucesos combina un cristal de HPGe, 4 orbes de datos y el catálogo multimensajero en la imagen de Sagitario A*. Solo funciona en la órbita de Plutón.")
    add('emi.grindless.info.event_horizon_interferometer.1', "El astrómetro de línea base usa la imagen.")
    add('emi.grindless.info.event_horizon_interferometer.2', 'Paso 8 del observatorio: una línea de base de la órbita de Plutón a la Tierra resuelve la sombra de Sgr A*, el agujero negro del corazón de la galaxia.')
    add('emi.grindless.info.event_horizon_interferometer.3', 'Circuito 1: el catálogo multimensajero (no se consume) + 1 cristal de HPGe (la etapa de entrada del receptor) + 4 orbes de datos -> 1 imagen de Sgr A*.')
    add('emi.grindless.info.event_horizon_interferometer.4', 'Solo en la órbita de Plutón. El Event Horizon Telescope fotografió Sgr A* en 2022 con una línea de base del tamaño de la Tierra; esta es una extrapolación ficticia de la VLBI espacial. La imagen es la investigación de la escotilla de energía UHV.')
    add('emi.grindless.info.event_horizon_interferometer.5', 'Necesita 9 x 9 x 5 de carcasa de celosía de estación (20 o más entre las piezas), una antena de 7 x 7 de bloques de aluminio, una carcasa de ordenador avanzada (el reloj máser), 1 o 2 escotillas de energía (UV), buses de entrada y buses de salida.')

    add('emi.grindless.info.fibre_draw_tower.0', "La torre de estirado de fibra fabrica productos de fibra óptica. Circuito 1: preforma de Yb. 2: estirar fibra. 3: módulo láser de fibra. 4: reacondicionar un módulo gastado. 5: láser de 1083 nm. 6: capilares huecos. 7: multifibra MCP. 8: láseres de enfriamiento. 9: preforma de almacenamiento de sílice. 10: pigtail de Er:YSO. 11: preforma de Er por MCVD.")
    add('emi.grindless.info.fibre_draw_tower.1', "Otras máquinas consumen el módulo láser de fibra y lo devuelven gastado para reacondicionarlo aquí.")
    add('emi.grindless.info.fibre_draw_tower.2', 'Fibra de doble revestimiento dopada con iterbio y el modulo laser de fibra, la fuente de luz de los laseres de UV. Circuito programado 1: tetracloruro de silicio + tetracloruro de germanio + oxido de iterbio + aluminio + oxigeno -> 1 preforma dopada con Yb (MCVD).')
    add('emi.grindless.info.fibre_draw_tower.3', 'Circuito 2: 1 preforma + 250 mB de recubrimiento de acrilato -> 16 bobinas de fibra de iterbio. Circuito 3: 4 bobinas de fibra + 4 modulos de bombeo InGaAs + 1 red de Bragg en fibra -> 1 modulo laser de fibra.')
    add('emi.grindless.info.fibre_draw_tower.4', 'Circuito 4: 1 modulo laser gastado + 1 bobina de fibra -> 1 modulo laser de fibra (reacondicionado). El cloro vuelve a tetracloruro de silicio y el hollin de silice a vidrio.')
    add('emi.grindless.info.fibre_draw_tower.5', 'Necesita una torre de carcasa de sala limpia de 5 x 15 x 5 (6 o mas entre las piezas del suelo), 1 o 2 hatches de energia (UV), buses y hatches de entrada y salida.')

    add('emi.grindless.info.heat_source_works.0', "La fábrica de fuentes de calor construye fuentes de calor radioisotópicas. Circuito 1: pellet de curio. 2: revestimiento GPHS. 3: RTG de sonda. 4: microfuente de americio. 5: pellet de curio para RTG.")
    add('emi.grindless.info.heat_source_works.1', "Nunca elimina residuos: el óxido de curio pesado se conserva para la línea de transuránicos.")
    add('emi.grindless.info.heat_source_works.2', 'Fuentes de calor de curio-244 tras muros de celda caliente. Circuito programado 1: 4 de oxido de curio -> 1 pastilla de curio-244 + 1 oxido de curio pesado (guardado para UHV). Circuito 2: 1 pastilla + 1 lamina de iridio + 1 aerocasco de carbono-carbono -> 1 modulo GPHS (+ chatarra de iridio, 25%).')
    add('emi.grindless.info.heat_source_works.3', 'Circuito 3: 4 modulos GPHS + 8 de polvo de silicio + 8 de polvo de germanio + 1 casco de maquina UV -> 1 RTG de sonda. Circuito 4: 1 de polvo de americio -> 8 microfuentes de americio.')
    add('emi.grindless.info.heat_source_works.4', 'Circuito 5: 1 pastilla de curio-244 -> 2 pastillas RTG de curio; la celda RTG de IV quema una durante 3 veces lo que una pastilla de plutonio. La chatarra vuelve a fundirse en la ruta de la lamina de iridio.')
    add('emi.grindless.info.heat_source_works.5', 'Necesita, en las filas delantera y trasera: 1 o 2 escotillas de energia (ZPM), 1 o 2 buses de entrada, 1 o 2 buses de salida y 4 o mas carcasas a prueba de radiacion entre ellos. Se niega a funcionar mientras anula.')

    add('emi.grindless.info.kuiper_interceptor_bay.0', "La bahía de interceptores de Kuiper lanza un interceptor de Kuiper con la carta Plutón-Kuiper y devuelve una muestra de planetesimal y un contenedor de muestras. Solo funciona en la órbita de Plutón.")
    add('emi.grindless.info.kuiper_interceptor_bay.1', "La muestra va al recocedor de hielo amorfo.")
    add('emi.grindless.info.kuiper_interceptor_bay.2', 'Un objeto frío clásico del cinturón de Kuiper, intacto desde que se formó el sistema solar. Circuito 1: 1 interceptor de Kuiper + la carta Plutón-Kuiper (no se consume) -> 1 muestra de planetesimal + 1 cápsula de muestras vacía.')
    add('emi.grindless.info.kuiper_interceptor_bay.3', 'El interceptor vuela con sus propulsores iónico y Hall, caldeado por su RTG, y trae la cápsula de vuelta a la estación, como hizo Hayabusa2 desde Ryugu.')
    add('emi.grindless.info.kuiper_interceptor_bay.4', 'Solo en la órbita de Plutón. Es la única fuente de la muestra de planetesimal; la cápsula vuelve al siguiente interceptor.')
    add('emi.grindless.info.kuiper_interceptor_bay.5', 'Necesita 7 x 7 x 9 de carcasa de celosía de estación (12 o más entre las piezas), bastidores de titanio (el raíl de lanzamiento), vidrio laminado (la esclusa de muestras), 1 o 2 escotillas de energía (UV), buses de entrada y buses de salida.')

    add('emi.grindless.info.laser_fusion_chamber.0', "La cámara de fusión láser es un generador de 2.621.440 EU/t. Circuito 1: cápsula de p-B11. Circuito 2: cápsula de D-He3. Cada ciclo necesita un módulo láser de fibra.")
    add('emi.grindless.info.laser_fusion_chamber.1', "El módulo láser gastado vuelve y se puede reacondicionar.")
    add('emi.grindless.info.laser_fusion_chamber.2', 'Fusion proton-boro-11: tres particulas alfa y casi ningun neutron. Una capsula por ejecucion paga 2.621.440 EU/t (5 A UV). Circuito programado 1: 1 capsula p-B11, 400 ticks, 3.000 mB de helio. Circuito 2: 1 capsula D-He-3, 600 ticks, 1.000 mB de helio + 1.000 mB de hidrogeno.')
    add('emi.grindless.info.laser_fusion_chamber.3', 'Cada ejecucion tiene un 2% de probabilidad de desgastar 1 modulo laser de fibra y dejarlo en un modulo laser gastado. El helio va al refrigerador de helio.')
    add('emi.grindless.info.laser_fusion_chamber.4', 'Una camara de 13x13x13 de carcasa UV con un anillo de 32 bloques de modulo laser en su cintura. En el suelo: 1-8 escotillas dinamo, 1 bus de entrada (el inyector de capsulas), 1-2 escotillas de salida, 1 bus de salida.')

    add('emi.grindless.info.laser_sail_launcher.0', "El lanzador de velas láser dispara velas desde la Luna. Circuito 1: lanza la sonda Starshot (nave de vela, datos de la heliopausa y un módulo láser de fibra). Circuito 2: lanza la semilla de relé.")
    add('emi.grindless.info.laser_sail_launcher.1', "Solo funciona en la Luna.")
    add('emi.grindless.info.laser_sail_launcher.2', 'Solo funciona en la Luna: no hay aire que disperse el haz. Un array en fase de 15 x 15 x 3 con 64 bloques de módulos láser, abierto al cielo.')
    add('emi.grindless.info.laser_sail_launcher.3', 'Cuatro cuadrantes de 4 x 4 módulos, un circuito de refrigeración de acero de wolframio alrededor y el director del haz (una carcasa de ordenador) en el centro.')
    add('emi.grindless.info.laser_sail_launcher.4', 'Un sail-chip por lanzamiento, apuntado con los datos de la heliopausa (se conservan): una sonda Starshot en vuelo. Consume 16 A de UV.')
    add('emi.grindless.info.laser_sail_launcher.5', 'Cada lanzamiento desgasta el array: un módulo de láser de fibra del bus se gasta al 64 % y sale como módulo gastado para la torre de estirado.')

    add('emi.grindless.info.light_sail_fab.0', "La fábrica de velas solares construye piezas de vela. Circuito 1: película de nitruro. 2: patrón de metasuperficie. 3: liberación de la vela. 4: película reflectora de aluminio. Solo funciona en la órbita de la Tierra.")
    add('emi.grindless.info.light_sail_fab.1', "La película reflectora también se usa para los segmentos del enjambre.")
    add('emi.grindless.info.light_sail_fab.2', 'Solo funciona en órbita terrestre: una película de 100 nm no sobrevive a la gravedad y al aire una vez liberada.')
    add('emi.grindless.info.light_sail_fab.3', 'Una caja de 7 x 7 x 7 de armazón de estación: un calentador de wolframio de 3 x 3 en la pared del fondo, una pared de escudo Whipple delante, las partes en el suelo.')
    add('emi.grindless.info.light_sail_fab.4', 'Circuito 1: silano y amoníaco depositan nitruro de silicio sobre una oblea epitaxial. 2: se graba una metasuperficie de hBN bajo la máscara de rayos X (se conserva).')
    add('emi.grindless.info.light_sail_fab.5', 'Circuito 3: el difluoruro de xenón elimina el silicio y libera la vela; el xenón vuelve y el tetrafluoruro de silicio se hidroliza.')

    add('emi.grindless.info.mocvd_reactor.0', "El reactor MOCVD hace crecer capas de semiconductor. Circuito 1: organometálicos. 2: epitaxia de InGaAs. 3: barras de diodos. 4: película de NbN. 5: módulo de bombeo. 6: depuración de arsina. 7: epitaxia IMM. 8: placa de NbN sobre SiC. 12: epitaxia de InGaAsSb.")
    add('emi.grindless.info.mocvd_reactor.1', "Las obleas alimentan láseres, módulos de bombeo y matrices solares.")
    add('emi.grindless.info.mocvd_reactor.2', 'Semiconductores compuestos crecidos capa atomica a capa atomica. Circuito 1: galio + indio + sodio + clorometano -> trimetilgalio + trimetilindio + sal.')
    add('emi.grindless.info.mocvd_reactor.3', 'Circuito 2: 1 oblea de GaAs + trimetilgalio + trimetilindio + arsina -> 1 oblea epitaxial de InGaAs + metano + arsina sin usar. Circuito 3: 1 oblea epitaxial -> 8 barras de diodos. Circuito 5: 4 barras de diodos + 2 placas de cobre -> 1 modulo de bombeo InGaAs.')
    add('emi.grindless.info.mocvd_reactor.4', 'Circuito 4: 1 oblea de zafiro + niobio + nitrogeno -> 1 oblea con pelicula de NbN. Circuito 6, el depurador de arsina: 1.000 mB de arsina -> 1 polvo de arsenico + 3.000 mB de hidrogeno. La arsina nunca se ventila.')
    add('emi.grindless.info.mocvd_reactor.5', 'Necesita carcasa de sala limpia de 7 x 7 x 7 con un armario de gases inerte (8 o mas entre las piezas), 1 o 2 hatches de energia (UV), buses y hatches de entrada y salida.')

    add('emi.grindless.info.muon_fusion_cell.0', "La celda de fusión por muones es un generador sin circuito: una manta reproductora de litio y 500 mB de deuterio-tritio líquido dan 500 mB de helio y 150 mB de tritio.")
    add('emi.grindless.info.muon_fusion_cell.1', "Funciona sin circuito.")
    add('emi.grindless.info.muon_fusion_cell.2', 'Los muones de un blanco de piones caen en deuterio-tritio líquido y catalizan la fusión a 20 K (Alvarez 1956, LAMPF, J-PARC). Da 786 432 EU/t. Una extrapolación: la fusión catalizada por muones real nunca ha llegado al equilibrio; esta celda supone una fracción de adherencia mucho menor.')
    add('emi.grindless.info.muon_fusion_cell.3', '500 mB de D-T líquido arden en 1200 ticks a helio. La manta de litio (nunca se gasta) regenera el 60 % del tritio; el otro 40 % es reemplazo de la instalación de retirada de tritio. El helio va a la planta de helio superfluido.')
    add('emi.grindless.info.muon_fusion_cell.4', 'Dos criomódulos SRF en la pared trasera impulsan el haz de piones. Las piezas van en la capa inferior: 1-2 escotillas de salida de energía, un bus de entrada, una escotilla de entrada, 1-2 escotillas de salida.')

    add('emi.grindless.info.neptune_deep_siphon.0', "El sifón profundo de Neptuno extrae gas de Neptuno. Circuito 4: hidrógeno y helio de Neptuno. Circuito 5: metano y sulfuro de hidrógeno. Necesita una muestra de Neptuno y una cabeza de cuchara, y solo funciona en la órbita de Neptuno.")
    add('emi.grindless.info.neptune_deep_siphon.1', "Conserva todas las salidas: no se elimina nada.")
    add('emi.grindless.info.neptune_deep_siphon.2', 'Baja el cazo con un cable más largo, por debajo de la capa de metano de Neptuno. La muestra de Neptuno (se conserva) le dice a qué profundidad. Solo hace las recetas de Neptuno del tipo sifón (el sifón de gigante de hielo las rechaza). Solo funciona en la órbita de Neptuno.')
    add('emi.grindless.info.neptune_deep_siphon.3', 'Circuito 4: 16.000 mB de hidrógeno de Neptuno + 4.000 mB de helio de Neptuno. 5: 4.000 mB de metano + 500 mB de sulfuro de hidrógeno. 491.520 EU/t (UV), 100 t. El cabezal del cazo se desgasta (0,25 % por ciclo).')
    add('emi.grindless.info.neptune_deep_siphon.4', 'Necesita: 1 o 2 escotillas de energía (UV), 1 o 2 buses de entrada, de 1 a 3 escotillas de salida y 14 o más carcasas de celosía de estación en el suelo. El torno del cable está en el centro.')

    add('emi.grindless.info.neural_culture_vat.0', "La cuba de cultivo neural hace crecer tejido neural. Circuito 1: 64 células madre a partir de gelatina, organoide neural y medio de crecimiento. Circuito 2: 4 unidades de procesamiento neural con 8 células madre y una PCB de wetware.")
    add('emi.grindless.info.neural_culture_vat.1', "Las células madre son también el punto de partida de los ordenadores de organoides de UHV.")
    add('emi.grindless.info.neural_culture_vat.2', 'Wetware por lotes; las recetas de GTM de celulas madre y unidades de neuroprocesamiento siguen funcionando. Circuito 1: 1.000 mB de medio de cultivo crudo + 4 polvos de gelatina -> 64 celulas madre + 250 mB de biomasa.')
    add('emi.grindless.info.neural_culture_vat.3', 'El circuito 1 necesita un organoide neural (del laboratorio de organoides) en el bus de entrada, no se consume: siembra el cultivo.')
    add('emi.grindless.info.neural_culture_vat.4', 'Circuito 2: 8 celulas madre + 1 placa de circuito impreso de wetware + 1.000 mB de medio de cultivo esterilizado -> 4 unidades de neuroprocesamiento + 250 mB de biomasa. Los cultivos fallidos se esterilizan en autoclave dentro.')
    add('emi.grindless.info.neural_culture_vat.5', 'Necesita una sala de plascreto de 7 x 7 x 7: ventanas de vidrio de sala limpia, un techo de 3 x 3 de carcasas de filtro, cuatro incubadoras de carcasa termorresistente y una bioimpresora de carcasa robusta; piezas en el suelo (30 o mas carcasas), 1 o 2 hatches de energia (UV).')

    add('emi.grindless.info.optical_ground_station.0', "La estación óptica terrestre convierte una sonda Starshot, una matriz SNSPD y 100 mB de helio superfluido en los datos de aproximación a Próxima. No tiene circuito.")
    add('emi.grindless.info.optical_ground_station.1', "Los datos hacen falta para abrir la puerta de salto y enviar el rover.")
    add('emi.grindless.info.optical_ground_station.2', 'El unico lector del Starshot: capta los fotones laser de la sonda a cuatro anos luz y los descodifica en datos de aproximacion a Proxima.')
    add('emi.grindless.info.optical_ground_station.3', '1 sonda Starshot en vuelo + 100 mB de helio superfluido -> 1 datos de aproximacion a Proxima + 100 mB de helio. Necesita una matriz SNSPD en el bus de entrada (no se consume).')
    add('emi.grindless.info.optical_ground_station.4', 'La matriz SNSPD se hace en la fabrica de qubits de ZPM (circuito 3) con una oblea con pelicula de NbN. El helio evaporado vuelve al congelador al vacio.')
    add('emi.grindless.info.optical_ground_station.5', 'Necesita una cupula de carcasa de maquina UV de 9 x 9 x 9: un espejo de 5 x 5 bloques de aluminio en el suelo, 3 carcasas de ordenador detras, el techo abierto en el centro; piezas en el suelo (50 o mas carcasas), 1 o 2 hatches de energia (UV).')

    add('emi.grindless.info.penetrator_probe_bay.0', "La bahía de sondas penetradoras dispara una sonda penetradora contra una luna. Circuito 1: núcleo de Sputnik. Circuito 2: núcleo de Caronte. Solo funciona en la órbita de Plutón.")
    add('emi.grindless.info.penetrator_probe_bay.1', "No se elimina nada; los núcleos van al fraccionador de hielos volátiles.")
    add('emi.grindless.info.penetrator_probe_bay.2', 'Lanza un penetrador a Sputnik Planitia o a Caronte y recoge el núcleo que envía arriba. El núcleo de hielo de Tritón (se conserva) lo calibra para los hielos de Kuiper. Solo funciona en la órbita de Plutón.')
    add('emi.grindless.info.penetrator_probe_bay.3', 'Circuito 1: 1 sonda penetradora -> 1 núcleo de hielo de Sputnik. Circuito 2: 1 sonda penetradora -> 1 núcleo de Caronte. 491.520 EU/t (UV), 200 t.')
    add('emi.grindless.info.penetrator_probe_bay.4', 'Necesita: 1 o 2 escotillas de energía (UV), 1 o 2 buses de entrada, 1 o 2 buses de salida y 14 o más carcasas de celosía de estación en el suelo. Un raíl de sonda de titanio sube por el centro hasta el recogedor de cápsulas (caja de engranajes de acero de tungsteno).')

    add('emi.grindless.info.powder_bed_printer.0', "La impresora de lecho de polvo fabrica piezas metálicas. Circuito 1: atomiza polvo. 2: engranaje o rotor casi final. 3: prensado. 4: cámara de propulsor. 5: soporte de matriz. 6: marco de sonda. 7: impulsor de Rea. 8: malla de wolframio.")
    add('emi.grindless.info.powder_bed_printer.1', "Cada impresión consume un módulo láser de fibra.")
    add('emi.grindless.info.powder_bed_printer.2', 'Piezas UV de una sola pieza con menos metal. El circuito 1 atomiza: 4 lingotes + 1.000 mB de argon -> 4 polvos AM + 950 mB de argon.')
    add('emi.grindless.info.powder_bed_printer.3', 'Imprimir gasta un modulo laser de fibra (2 % de desgaste: sale un modulo gastado con la misma probabilidad). Circuito 2: engranajes de neutronio y tritanio y rotores de darmstadtio al 75 % de los lingotes; circuitos 4 a 6: la camara del propulsor, el soporte del array y el bastidor de sonda.')
    add('emi.grindless.info.powder_bed_printer.4', 'El circuito 3 prensa la pieza casi final: + 1.000 mB de argon -> la pieza, con todo el argon de vuelta. El polvo sin sinterizar y las salpicaduras vuelven al lecho.')
    add('emi.grindless.info.powder_bed_printer.5', 'Necesita carcasa UV de 7 x 7 x 7 (8 o mas entre las piezas), bobinas de naquadah, carcasa de tuberia de PTFE, rejilla de cadena de montaje, carcasa de hogar de acero de tungsteno y marcos, 1 o 2 hatches de energia (UV), buses y hatches de entrada y salida.')

    add('emi.grindless.info.powder_in_tube_line.0', "La línea de polvo en tubo fabrica cable superconductor. Circuito 1: polvo de EnTED. 2: lingote. 3: cable de EnTED. 4: cable de RTAN. 5: cable de MgB2 en tubo de hierro. 6: cable de superhidruro de LaY.")
    add('emi.grindless.info.powder_in_tube_line.1', "Los cables se usan en escotillas y estructuras superconductoras de las eras posteriores.")
    add('emi.grindless.info.powder_in_tube_line.2', 'Cable de EnTED, el superconductor UV de GTM, a cuatro cables por lingote de polvo. Circuito 1: 4 de naquadah enriquecido + 3 de trinio + 2 de europio + 1 de duranio en polvo -> 10 polvos de EnTED.')
    add('emi.grindless.info.powder_in_tube_line.3', 'Circuito 2: 4 polvos de EnTED + 1 tubo de plata -> 1 tocho PIT. Circuito 3: 1 tocho -> 16 cables simples de EnTED + 1 polvo de plata (la funda, que vuelve a ser tubo).')
    add('emi.grindless.info.powder_in_tube_line.4', 'El unico que hace cable de EnTED: ya no hay trefiladora, extrusora ni cortacables. Duplicar, el cable fino y los cables aislados siguen saliendo de su cable simple.')
    add('emi.grindless.info.powder_in_tube_line.5', 'Necesita una linea de carcasa UV de 3 x 5 x 15 (8 o mas entre las piezas), carcasa de tuberia de acero, cajas de engranajes de acero de tungsteno, unidades de cadena de montaje, bobinas de trinio, 1 o 2 hatches de energia (UV), buses de entrada y salida.')

    add('emi.grindless.info.precursor_probe_bay.0', "La bahía de sondas precursoras lanza una sonda precursora con 4 pellets ICAN y devuelve los datos de la heliopausa. Solo funciona en la órbita de Plutón.")
    add('emi.grindless.info.precursor_probe_bay.1', "Los datos los usan el lanzador de velas láser y la bahía de sondas solares.")
    add('emi.grindless.info.precursor_probe_bay.2', 'La primera sonda hasta la heliopausa, donde el viento del Sol choca con el medio interestelar. Circuito 1: 1 sonda precursora + 4 pastillas ICAN -> 1 datos de la heliopausa.')
    add('emi.grindless.info.precursor_probe_bay.3', 'Un impulso ICAN desde la órbita de Plutón y después años de propulsores iónicos hasta 150 UA, como planeó el estudio Interstellar Probe de JHU/APL tras el cruce de la Voyager 1 en 2012. La sonda se gasta.')
    add('emi.grindless.info.precursor_probe_bay.4', 'Solo en la órbita de Plutón, 2 A UV. Es la única fuente de los datos de la heliopausa: el lanzador de velas láser los necesita para apuntar el Starshot.')
    add('emi.grindless.info.precursor_probe_bay.5', 'Necesita 7 x 7 x 11 de carcasa de celosía de estación (16 o más entre las piezas), bastidores de titanio (el raíl de lanzamiento), carcasa de ordenador (el relé DSN), 1 o 2 escotillas de energía (UV), buses de entrada y buses de salida.')

    add('emi.grindless.info.pyroprocessing_cell.0', "La celda de piroprocesado reprocesa combustible. Circuito 1: reduce el combustible de óxido gastado a metal ThU. 2: refina U-233 y torio. 3: combustible de nitruro (vuelve el N-15). 4: limpia la sal cargada. 5: fila del impulsor HFIR. 6: esponja de Ti-50. 7: metal de Ni-58. 8: metal de Li-6. 9: eutéctico Li-Sn.")
    add('emi.grindless.info.pyroprocessing_cell.1', "No elimina residuos.")
    add('emi.grindless.info.pyroprocessing_cell.2', 'El pirorrefinado en sal fundida de EBR-II: el combustible de torio gastado se reduce con litio en un baño de LiCl y el uranio-233 se recoge en un cátodo.')
    add('emi.grindless.info.pyroprocessing_cell.3', 'Circuito 1: combustible de óxido gastado a metal de torio y uranio. 2: el metal a uranio-233 y torio. 3: combustible de nitruro gastado a uranio-233, torio y nitrógeno-15 (reemplazo del 5 % de N-14). 4: la sal cargada se limpia; su residuo va a la planta de recuperación de residuos. 5: los elementos impulsores gastados del reactor de alto flujo vuelven a uranio-233.')
    add('emi.grindless.info.pyroprocessing_cell.4', 'La sal y el litio son cargas que nunca se gastan. Las piezas van en la capa inferior: 1-2 escotillas de energía, un bus de entrada, 1-2 escotillas de entrada, 1-2 buses de salida, 1-2 escotillas de salida.')

    add('emi.grindless.info.srf_cavity_works.0', "La fábrica de cavidades SRF construye cavidades superconductoras. Circuito 1: láminas de niobio RRR. 2: cavidad desnuda. 3: tratamiento de superficie con ácido de electropulido. 4: criomódulo (necesita helio superfluido). 5: difusión de Nb3Sn y blanco de para-H2. 6: hielo de H polarizado. 7: cono de neón sólido.")
    add('emi.grindless.info.srf_cavity_works.1', "Las cavidades son piezas para aceleradores y criomódulos.")
    add('emi.grindless.info.srf_cavity_works.2', 'El criomodulo de radiofrecuencia superconductor, la pieza base de todo acelerador UV. Circuito programado 1: 4 lingotes de niobio -> 3 laminas de niobio RRR + 1 chatarra de niobio (la chatarra vuelve a fundirse en un lingote).')
    add('emi.grindless.info.srf_cavity_works.3', 'Circuito 2: 9 laminas RRR -> 1 cavidad desnuda. Circuito 3: 1 cavidad desnuda + 500 mB de acido de electropulido + 100 mB de nitrogeno -> 1 cavidad dopada con N + 500 mB de acido gastado.')
    add('emi.grindless.info.srf_cavity_works.4', 'Circuito 4: 8 cavidades + 4.000 mB de helio superfluido + 2 generadores de campo UV + 1 blindaje de mu-metal -> 1 criomodulo SRF. El acido gastado se recupera como niobio y fluorita, y la fluorita vuelve a dar acido fluorhidrico.')
    add('emi.grindless.info.srf_cavity_works.5', 'Necesita carcasa de sala limpia de 7 x 7 x 9 (8 o mas entre las piezas), 1 o 2 hatches de energia (UV), buses y hatches de entrada y salida.')

    add('emi.grindless.info.starchip_fab.0', "La fábrica de starchips construye hardware interestelar. Circuito 1: starchip. 2: nave de vela. 3: semilla de relé. 4: sonda de ergosfera. Solo funciona en la órbita de la Tierra y necesita sala limpia.")
    add('emi.grindless.info.starchip_fab.1', "Las naves de vela y las semillas de relé las lanza el lanzador de velas láser.")
    add('emi.grindless.info.starchip_fab.2', 'Una caja de sala limpia de 5 x 5 x 5 con techo de carcasas de filtro y la soldadora (una caja de engranajes de acero inoxidable) en el centro del suelo.')
    add('emi.grindless.info.starchip_fab.3', 'Circuito 1: un chip fotónico, un chip de diamante NV y una microfuente de americio unidos sobre una oblea de neutronio: un starchip de pocos gramos.')
    add('emi.grindless.info.starchip_fab.4', 'Circuito 2: el starchip montado en una vela de luz: un sail-chip listo para el lanzador de la Luna.')
    add('emi.grindless.info.starchip_fab.5', 'El corte de la oblea sale como polvo de silicio.')

    add('emi.grindless.info.superfluid_helium_plant.0', "La planta de helio superfluido no tiene circuito. Hace helio superfluido a partir de helio líquido o de helio de Neptuno (con concentrado de helio-3 como subproducto), mezcla helio-3 y helio-4 y separa la ceniza de PLi6 en helio-3 y helio.")
    add('emi.grindless.info.superfluid_helium_plant.1', "El helio superfluido enfría las cavidades, la trampa de antimateria y la estación óptica.")
    add('emi.grindless.info.superfluid_helium_plant.2', 'Helio II a 1,9 K, por debajo del punto lambda, que el refrigerador de 4 K de LuV no alcanza. Enfria las cavidades SRF y el receptor SNSPD.')
    add('emi.grindless.info.superfluid_helium_plant.3', 'Helio liquido (del refrigerador de helio): 1.000 mB -> 1.000 mB de helio superfluido. Solo recetas de fluidos: sin circuito.')
    add('emi.grindless.info.superfluid_helium_plant.4', 'Superfuga: 1.000 mB de helio de Neptuno -> 990 mB de helio superfluido + 10 mB de concentrado de helio-3 (solo pasa el helio-4). El concentrado va a la columna de isotopos.')
    add('emi.grindless.info.superfluid_helium_plant.5', 'Necesita carcasa anticongelante de 7 x 7 x 9 (8 o mas entre las piezas), 1 o 2 hatches de energia (UV), 1 o 2 hatches de entrada y 1 o 2 de salida.')

    add('emi.grindless.info.synchrotron.0', "El sincrotrón trabaja con rayos X. Circuito 1: expone una oblea de PMMA. 2: revelado LIGA. 3: chips fotónicos. 4: antiprotones (el blanco de wolframio activado vuelve como subproducto). 5: blanco de sodio-22. 6: litografía de guías de onda de SiN. 7: litografía de zanjas damasquinadas.")
    add('emi.grindless.info.synchrotron.1', "Aquí se hacen los antiprotones.")
    add('emi.grindless.info.synchrotron.2', 'Un anillo de 23 x 23: 16 dipolos superconductores curvan el haz, dos criomódulos SRF le dan energía y dos líneas de haz lo sacan. Sus rayos X hacen el proceso LIGA del KIT; sus protones sobre un blanco de wolframio dan los únicos antiprotones del pack.')
    add('emi.grindless.info.synchrotron.3', 'Circuito 1: una oblea con PMMA expuesta bajo una máscara de rayos X de oro (se conserva). 2: revelada en el revelador LIGA (nunca se gasta). 3: con una película de nitruro de silicio, 4 chips fotónicos. 4: 16 protones a un cartucho de antiprotones; el blanco de wolframio se gasta un 2 % por ciclo y sale activado.')
    add('emi.grindless.info.synchrotron.4', 'El blanco activado se enfría en un baño químico y vuelve a polvo de wolframio y cobre; casi todo el haz se recombina en hidrógeno. Las piezas van en la capa inferior: 1-4 escotillas de energía, 1-2 buses de entrada, una escotilla de entrada, 1-2 buses de salida, una escotilla de salida.')

    add('emi.grindless.info.thruster_works.0', "La fábrica de propulsores construye propulsión. Circuito 1: propulsor iónico (xenón). 2: propulsor Hall (kriptón). 3: cápsula de propulsor. 4: motor de cohete ICAN. 5: cápsula de propelente de oganesón. 6: motor DFD Mk1. 7: motor DFD Mk2.")
    add('emi.grindless.info.thruster_works.1', "Las cápsulas de oganesón son el combustible del enjambre.")
    add('emi.grindless.info.thruster_works.2', 'Propulsores eléctricos para las sondas. Circuito 1: 2 rejillas de molibdeno + 1 cátodo de LaB6 + 1 cámara de propulsor impresa + 4.000 mB de xenón -> 1 propulsor iónico de rejillas + 3.600 mB de xenón.')
    add('emi.grindless.info.thruster_works.3', 'Circuito 2: 1 canal de descarga de BN + 4 electroimanes UV + 1 cátodo de LaB6 + 4.000 mB de kriptón (de la mezcla de gases nobles de Kuiper) -> 1 propulsor Hall + 3.600 mB de kriptón. El encendido pierde una décima parte del gas.')
    add('emi.grindless.info.thruster_works.4', 'Circuito 3: 1 propulsor iónico + 1 propulsor Hall + 1 circuito UV (la unidad de procesamiento de potencia) + 1 tanque de propelente -> 1 módulo de propulsores.')
    add('emi.grindless.info.thruster_works.5', 'Necesita 7 x 7 x 9 de carcasa UV (8 o más entre las piezas), vidrio laminado (la celda de pruebas de vacío), rejilla y unidades de línea de ensamblaje (la bahía de montaje), 1 o 2 escotillas de energía (UV), buses y escotillas de entrada y salida.')

    add('emi.grindless.info.triton_geyser_sampler.0', "El muestreador de géiseres de Tritón trabaja con un cartucho de aerogel. Circuito 1: con la grabación de la sonda de Tritón, tolina y nitrógeno de Tritón. Circuito 2: núcleo de hielo de Tritón y nitrógeno. Solo funciona en la órbita de Neptuno.")
    add('emi.grindless.info.triton_geyser_sampler.1', "No se elimina nada.")
    add('emi.grindless.info.triton_geyser_sampler.2', 'Hace volar un cartucho de aerogel a través de los géiseres de nitrógeno de Tritón. La grabación de la sonda de Tritón (se conserva) le dice dónde entran en erupción. Solo funciona en la órbita de Neptuno.')
    add('emi.grindless.info.triton_geyser_sampler.3', 'Circuito 1: 1 cartucho de aerogel -> 8.000 mB de nitrógeno de Tritón + 1 tolina. Circuito 2: 1 cartucho de aerogel -> 1 núcleo de hielo de Tritón + 2.000 mB de nitrógeno de Tritón. 491.520 EU/t (UV), 200 t.')
    add('emi.grindless.info.triton_geyser_sampler.4', 'Necesita: 1 o 2 escotillas de energía (UV), 1 o 2 buses de entrada, 1 o 2 buses de salida, 1 o 2 escotillas de salida y 14 o más carcasas de celosía de estación en el suelo. Un raíl de lanzamiento de titanio cruza el centro.')

    add('emi.grindless.info.volatile_ice_fractionator.0', "El fraccionador de hielos volátiles separa núcleos. Circuito 1: núcleo de Sputnik en tolina, nitrógeno, monóxido de carbono y metano. Circuito 2: núcleo de Caronte en sílice, agua y amoníaco. Solo funciona en la órbita de Plutón.")
    add('emi.grindless.info.volatile_ice_fractionator.1', "No se elimina nada.")
    add('emi.grindless.info.volatile_ice_fractionator.2', 'Calienta un núcleo paso a paso en un dedo frío: cada hielo sublima a su propia temperatura (nitrógeno, luego monóxido de carbono, luego metano). Solo funciona en la órbita de Plutón.')
    add('emi.grindless.info.volatile_ice_fractionator.3', 'Circuito 1: 1 núcleo de hielo de Sputnik -> 16.000 mB de nitrógeno + 2.000 mB de monóxido de carbono + 1.000 mB de metano + 1 tolina. Circuito 2: 1 núcleo de Caronte -> 8.000 mB de agua + 2.000 mB de amoníaco + 1 polvo de dióxido de silicio. 122.880 EU/t (ZPM), 600 t.')
    add('emi.grindless.info.volatile_ice_fractionator.4', 'Necesita: 1 o 2 escotillas de energía (UV), 1 o 2 buses de entrada, 1 o 2 buses de salida, de 1 a 3 escotillas de salida y 14 o más carcasas de celosía de estación en el suelo. El dedo frío escalonado (carcasas de tubería de acero, marcos de titanio) está en el centro.')

    add('emi.grindless.info.zone_refining_tower.0', "La torre de refinado por zonas purifica cristales. Circuito 1: GeCl4. 2: reducción de germanio. 3: cristal de HPGe. 4: silicio de zona flotante. 5: indio 7N. 6: lingote de Si-28 de zona flotante. 7: recrecimiento de donante de Si-28.")
    add('emi.grindless.info.zone_refining_tower.1', "Los cristales de HPGe van a detectores e interferómetros.")
    add('emi.grindless.info.zone_refining_tower.2', 'Germanio de alta pureza, trece nueves, para el cristal de HPGe. Circuito programado 1: 1 polvo de germanio + 4.000 mB de cloro -> 1.000 mB de tetracloruro de germanio (tambien el dopante de la preforma de fibra).')
    add('emi.grindless.info.zone_refining_tower.3', 'Circuito 2: 1.000 mB de tetracloruro de germanio + 2.000 mB de agua + 4.000 mB de hidrogeno -> 1 lingote de germanio + 4.000 mB de acido clorhidrico; el agua se recupera.')
    add('emi.grindless.info.zone_refining_tower.4', 'Circuito 3: 4 lingotes de germanio -> 1 cristal de HPGe + 1 polvo de germanio (los extremos impuros, de vuelta al circuito 1). Ocho bobinas de RF barren la zona fundida por la barra y el extractor crece el cristal.')
    add('emi.grindless.info.zone_refining_tower.5', 'Necesita una torre de carcasa de sala limpia de 3 x 13 x 3: 8 bloques de bobina de naquadah en el nucleo y una caja de engranajes de acero inoxidable arriba; piezas en el suelo y la pared trasera (6 o mas carcasas), 1 o 2 hatches de energia (UV).')
})
